package com.example.takura.privacy.application;
import com.example.takura.identity.domain.StaffPrincipal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class PrivacyOperationsService{private final JdbcTemplate jdbc;private final Clock clock;public PrivacyOperationsService(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 @Transactional public Request create(StaffPrincipal p,UUID enquiry,Command c){require(p,"privacy:manage");if(!Set.of("ACCESS","CORRECTION","DELETION").contains(c.type())||blank(c.identityEvidenceReference())||blank(c.scope()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"PRIVACY_REQUEST_INVALID");UUID id=UUID.randomUUID();String number="PRV-"+clock.instant().atZone(ZoneOffset.UTC).getYear()+"-"+id.toString().substring(0,8).toUpperCase();jdbc.update("INSERT INTO takura.privacy_request(id,request_number,enquiry_id,request_type,state,identity_evidence_reference,scope_description,requested_at,requested_by) VALUES(?,?,?,?,'OPEN',?,?,?,?)",id,number,enquiry,c.type(),trim(c.identityEvidenceReference(),200),trim(c.scope(),500),now(),p.identityId());audit(p,id,"PRIVACY_REQUEST_CREATED",Map.of("type",c.type()));return get(id);}
 @Transactional public Request approve(StaffPrincipal p,UUID id,long revision){require(p,"privacy:approve");int n=jdbc.update("UPDATE takura.privacy_request SET state='APPROVED',approved_at=?,approved_by=?,revision=revision+1 WHERE id=? AND state='OPEN' AND revision=? AND requested_by<>?",now(),p.identityId(),id,revision,p.identityId());if(n!=1)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"PRIVACY_APPROVAL_CONFLICT");audit(p,id,"PRIVACY_REQUEST_APPROVED",Map.of());return get(id);}
 public String accessCsv(StaffPrincipal p,UUID id){require(p,"privacy:export");Request r=get(id);if(!"ACCESS".equals(r.type())||!"APPROVED".equals(r.state()))throw new ResponseStatusException(HttpStatus.CONFLICT,"PRIVACY_ACCESS_NOT_APPROVED");var row=jdbc.query("SELECT reference,full_name,email,phone,preferred_contact,country_code,town_or_suburb,description,privacy_notice_version,marketing_opt_in,created_at FROM takura.enquiry WHERE id=?",(rs,n)->new String[]{rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getString(9),Boolean.toString(rs.getBoolean(10)),rs.getTimestamp(11).toInstant().toString()},r.enquiryId()).getFirst();StringBuilder out=new StringBuilder("reference,full_name,email,phone,preferred_contact,country,area,description,privacy_notice_version,marketing_opt_in,created_at\n");for(int i=0;i<row.length;i++){if(i>0)out.append(',');out.append(csv(row[i]));}out.append('\n');audit(p,id,"PRIVACY_ACCESS_EXPORTED",Map.of("fields",row.length));return out.toString();}
 @Transactional public Request executeCorrection(StaffPrincipal p,UUID id,long revision,Correction c){require(p,"privacy:manage");Request r=get(id);if(!"CORRECTION".equals(r.type())||!"APPROVED".equals(r.state())||r.revision()!=revision||blank(c.fullName())||blank(c.area()))throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"PRIVACY_CORRECTION_CONFLICT");jdbc.update("UPDATE takura.enquiry SET full_name=?,email=COALESCE(?,email),phone=COALESCE(?,phone),town_or_suburb=?,revision=revision+1 WHERE id=?",trim(c.fullName(),120),blank(c.email())?null:trim(c.email(),254),blank(c.phone())?null:trim(c.phone(),80),trim(c.area(),120),r.enquiryId());jdbc.update("UPDATE takura.privacy_request SET state='COMPLETED',actioned_at=?,actioned_by=?,outcome='Approved correction applied',revision=revision+1 WHERE id=?",now(),p.identityId(),id);audit(p,id,"PRIVACY_CORRECTION_COMPLETED",Map.of("fields",4));return get(id);}
 @Transactional public Request executeDeletion(StaffPrincipal p,UUID id,long revision,String outcome){require(p,"privacy:delete");Request r=get(id);if(!"DELETION".equals(r.type())||!"APPROVED".equals(r.state())||r.revision()!=revision)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"PRIVACY_DELETION_CONFLICT");if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM takura.legal_hold WHERE enquiry_id=? AND active)",Boolean.class,r.enquiryId()))){jdbc.update("UPDATE takura.privacy_request SET state='BLOCKED_BY_HOLD',revision=revision+1,outcome=? WHERE id=?",trim(outcome,500),id);audit(p,id,"PRIVACY_DELETION_BLOCKED",Map.of("hold",true));return get(id);}String ref=jdbc.queryForObject("SELECT reference FROM takura.enquiry WHERE id=? FOR UPDATE",String.class,r.enquiryId());jdbc.update("INSERT INTO takura.deletion_tombstone(id,enquiry_id,enquiry_reference_hash,reason,deletion_version,state,deleted_at) VALUES(?,?,?,'AUTHORISED_PRIVACY_REQUEST','privacy-v1','PENDING',?) ON CONFLICT DO NOTHING",UUID.randomUUID(),r.enquiryId(),hash(ref),now());jdbc.update("UPDATE takura.quote_access_session s SET revoked_at=? FROM takura.customer_quote_grant g JOIN takura.quote_revision q ON q.id=g.quote_revision_id JOIN takura.quote_group x ON x.id=q.quote_group_id WHERE s.grant_id=g.id AND x.enquiry_id=? AND s.revoked_at IS NULL",now(),r.enquiryId());jdbc.update("UPDATE takura.customer_quote_grant g SET revoked_at=?,state='REVOKED' FROM takura.quote_revision q JOIN takura.quote_group x ON x.id=q.quote_group_id WHERE g.quote_revision_id=q.id AND x.enquiry_id=? AND g.revoked_at IS NULL",now(),r.enquiryId());jdbc.update("UPDATE takura.notification_outbox SET state='FAILED_REQUIRES_REVIEW',failure_code='PRIVACY_DELETION',lease_until=NULL,leased_by=NULL WHERE aggregate_id=? AND state IN ('PENDING','LEASED','DELIVERY_UNKNOWN')",r.enquiryId());jdbc.update("UPDATE takura.attachment SET state='DELETION_PENDING',revision=revision+1 WHERE enquiry_id=? AND state NOT IN ('DELETED','DELETION_PENDING')",r.enquiryId());jdbc.update("UPDATE takura.enquiry SET full_name='Deleted customer',email='deleted@privacy.example.invalid',phone=NULL,preferred_contact='EMAIL',town_or_suburb='Deleted',description='Deleted under authorised privacy workflow',marketing_opt_in=false,revision=revision+1 WHERE id=?",r.enquiryId());jdbc.update("UPDATE takura.privacy_request SET state='COMPLETED',actioned_at=?,actioned_by=?,outcome=?,revision=revision+1 WHERE id=?",now(),p.identityId(),trim(outcome,500),id);jdbc.update("UPDATE takura.deletion_tombstone SET state='APPLIED' WHERE enquiry_id=? AND deletion_version='privacy-v1'",r.enquiryId());audit(p,id,"PRIVACY_DELETION_COMPLETED",Map.of("tombstone",true));return get(id);}
 @Transactional public UUID placeHold(StaffPrincipal p,UUID enquiry,String reason){require(p,"privacy:hold");if(blank(reason))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"HOLD_REASON_REQUIRED");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO takura.legal_hold(id,enquiry_id,reason,created_by,created_at) VALUES(?,?,?,?,?)",id,enquiry,trim(reason,500),p.identityId(),now());audit(p,id,"LEGAL_HOLD_PLACED",Map.of());return id;}
 @Transactional public void withdrawMarketing(StaffPrincipal p,UUID enquiry,String noticeVersion){require(p,"privacy:manage");String email=jdbc.queryForObject("SELECT email FROM takura.enquiry WHERE id=? FOR UPDATE",String.class,enquiry);jdbc.update("UPDATE takura.enquiry SET marketing_opt_in=false,revision=revision+1 WHERE id=?",enquiry);jdbc.update("INSERT INTO takura.marketing_consent_event(id,enquiry_id,consented,notice_version,evidence_source,occurred_at) VALUES(?,?,false,?,'STAFF_ASSISTED',?)",UUID.randomUUID(),enquiry,trim(noticeVersion,80),now());if(email!=null)jdbc.update("INSERT INTO takura.communication_suppression(id,channel,destination_hash,reason,created_at) VALUES(?,'EMAIL',?,'OPT_OUT',?) ON CONFLICT(channel,destination_hash) DO UPDATE SET active=true,reason='OPT_OUT'",UUID.randomUUID(),hash(email.toLowerCase()),now());audit(p,enquiry,"MARKETING_CONSENT_WITHDRAWN",Map.of("notice_version_recorded",true));}
 public int markRetentionEligible(){Instant cutoff=clock.instant().minus(Duration.ofDays(365));return jdbc.update("INSERT INTO takura.deletion_tombstone(id,enquiry_id,enquiry_reference_hash,reason,deletion_version,state,deleted_at) SELECT gen_random_uuid(),e.id,md5(e.reference)||md5(e.reference),'RETENTION_REVIEW','retention-v1','PENDING',? FROM takura.enquiry e WHERE e.state IN ('CLOSED','LOST','SPAM') AND e.created_at<? AND NOT EXISTS(SELECT 1 FROM takura.legal_hold h WHERE h.enquiry_id=e.id AND h.active) AND NOT EXISTS(SELECT 1 FROM takura.deletion_tombstone d WHERE d.enquiry_id=e.id AND d.deletion_version='retention-v1')",now(),Timestamp.from(cutoff));}
 @Transactional public int replayTombstones(){var ids=jdbc.query("SELECT enquiry_id FROM takura.deletion_tombstone d WHERE reason='AUTHORISED_PRIVACY_REQUEST' AND state IN ('PENDING','APPLIED','FAILED_RETRYABLE') AND NOT EXISTS(SELECT 1 FROM takura.legal_hold h WHERE h.enquiry_id=d.enquiry_id AND h.active)",(rs,n)->(UUID)rs.getObject(1));int applied=0;for(UUID enquiry:ids){applied+=jdbc.update("UPDATE takura.enquiry SET full_name='Deleted customer',email='deleted@privacy.example.invalid',phone=NULL,preferred_contact='EMAIL',town_or_suburb='Deleted',description='Deleted under authorised privacy workflow',marketing_opt_in=false WHERE id=? AND (full_name<>'Deleted customer' OR marketing_opt_in)",enquiry);jdbc.update("UPDATE takura.notification_outbox SET state='FAILED_REQUIRES_REVIEW',failure_code='PRIVACY_DELETION',lease_until=NULL,leased_by=NULL WHERE aggregate_id=? AND state IN ('PENDING','LEASED','DELIVERY_UNKNOWN')",enquiry);jdbc.update("UPDATE takura.deletion_tombstone SET state='APPLIED',last_error_code=NULL WHERE enquiry_id=? AND reason='AUTHORISED_PRIVACY_REQUEST'",enquiry);}return applied;}
 public Request get(UUID id){var rows=jdbc.query("SELECT id,request_number,enquiry_id,request_type,state,revision FROM takura.privacy_request WHERE id=?",(rs,n)->new Request((UUID)rs.getObject(1),rs.getString(2),(UUID)rs.getObject(3),rs.getString(4),rs.getString(5),rs.getLong(6)),id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"PRIVACY_REQUEST_NOT_FOUND");return rows.getFirst();}
 private void audit(StaffPrincipal p,UUID id,String action,Map<String,Object> m){jdbc.update("INSERT INTO takura.operational_audit(id,actor_identity_id,target_type,target_id,action,outcome,metadata,occurred_at) VALUES(?,?, 'PRIVACY_REQUEST',?,?, 'SUCCESS',?::jsonb,?)",UUID.randomUUID(),p.identityId(),id,action,"{}",now());}private void require(StaffPrincipal p,String op){if(!p.may(op))throw new AccessDeniedException("Required privacy operation is not granted");}private Timestamp now(){return Timestamp.from(clock.instant());}private static boolean blank(String s){return s==null||s.isBlank();}private static String trim(String s,int n){s=s.trim();return s.length()>n?s.substring(0,n):s;}private static String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static String csv(String s){s=s==null?"":s;if(!s.isEmpty()&&"=+-@".indexOf(s.charAt(0))>=0)s="'"+s;return '"'+s.replace("\"","\"\"")+'"';}
 public record Command(String type,String identityEvidenceReference,String scope){}public record Correction(String fullName,String email,String phone,String area){}public record Request(UUID id,String number,UUID enquiryId,String type,String state,long revision){}
}
